import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/ui-config/migration.html","title":"配置迁移","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":2,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"}]},"filePathRelative":"guide/ui-config/migration.md"}`),a={name:`migration.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="配置迁移" tabindex="-1"><a class="header-anchor" href="#配置迁移">#</a> 配置迁移</h1><p>配置迁移功能用于在不同环境或渠道间复制配置，支持选择性迁移和冲突处理。本指南将帮助你高效管理配置迁移。</p><h2 id="概念说明" tabindex="-1"><a class="header-anchor" href="#概念说明">#</a> 概念说明</h2><h3 id="什么是配置迁移" tabindex="-1"><a class="header-anchor" href="#什么是配置迁移">#</a> 什么是配置迁移？</h3><p>配置迁移是指将配置从一个环境/渠道复制到另一个环境/渠道的过程，常用于：</p><table><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>环境升级</td><td>开发环境 → 测试环境 → 生产环境</td></tr><tr><td>渠道同步</td><td>主渠道配置 → 热修复渠道</td></tr><tr><td>配置复制</td><td>快速创建相似配置</td></tr><tr><td>灾难恢复</td><td>从备份环境恢复配置</td></tr></tbody></table><h3 id="迁移方式" tabindex="-1"><a class="header-anchor" href="#迁移方式">#</a> 迁移方式</h3><p>系统支持两种迁移方式：</p><ol><li><strong>直接迁移</strong>：在线复制，无需下载</li><li><strong>导入迁移</strong>：通过导出包导入</li></ol><h2 id="直接迁移" tabindex="-1"><a class="header-anchor" href="#直接迁移">#</a> 直接迁移</h2><h3 id="通过-ui-迁移" tabindex="-1"><a class="header-anchor" href="#通过-ui-迁移">#</a> 通过 UI 迁移</h3><ol><li>进入 <strong>配置迁移</strong> 页面</li><li>选择 <strong>直接迁移</strong> 模式</li><li>配置迁移参数： <ul><li><strong>源环境</strong>：选择源环境</li><li><strong>源渠道</strong>：选择源渠道</li><li><strong>目标环境</strong>：选择目标环境</li><li><strong>目标渠道</strong>：选择目标渠道</li></ul></li><li>选择要迁移的配置</li><li>选择冲突处理方式： <ul><li>跳过已存在的配置</li><li>覆盖已存在的配置</li></ul></li><li>点击 <strong>开始迁移</strong></li><li>查看迁移结果</li></ol><h3 id="通过-api-迁移" tabindex="-1"><a class="header-anchor" href="#通过-api-迁移">#</a> 通过 API 迁移</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/migrate <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;source_environment&quot;: &quot;dev&quot;,</span>
<span class="line">    &quot;source_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;target_environment&quot;: &quot;test&quot;,</span>
<span class="line">    &quot;target_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;resource_keys&quot;: [&quot;uuid-1&quot;, &quot;uuid-2&quot;, &quot;uuid-3&quot;],</span>
<span class="line">    &quot;overwrite&quot;: false</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>响应示例</strong>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;migrated&quot;</span><span class="token operator">:</span> <span class="token number">3</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;skipped&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;failed&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;details&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;api_base_url&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;status&quot;</span><span class="token operator">:</span> <span class="token string">&quot;migrated&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;theme_color&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;status&quot;</span><span class="token operator">:</span> <span class="token string">&quot;skipped&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;已存在，跳过覆盖&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="导入迁移" tabindex="-1"><a class="header-anchor" href="#导入迁移">#</a> 导入迁移</h2><p>当需要跨实例迁移或从备份恢复时，使用导入迁移。</p><h3 id="步骤-1-导出配置" tabindex="-1"><a class="header-anchor" href="#步骤-1-导出配置">#</a> 步骤 1：导出配置</h3><p>从源环境导出配置包：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/export <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;selections&quot;: [</span>
<span class="line">      {</span>
<span class="line">        &quot;environment_key&quot;: &quot;dev&quot;,</span>
<span class="line">        &quot;pipeline_key&quot;: &quot;main&quot;,</span>
<span class="line">        &quot;resource_keys&quot;: [&quot;uuid-1&quot;, &quot;uuid-2&quot;]</span>
<span class="line">      }</span>
<span class="line">    ]</span>
<span class="line">  }&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-o</span> export.zip</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="步骤-2-预览导入" tabindex="-1"><a class="header-anchor" href="#步骤-2-预览导入">#</a> 步骤 2：预览导入</h3><p>导入前预览，检查冲突：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/import-preview <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@export.zip&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=test&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="步骤-3-执行导入" tabindex="-1"><a class="header-anchor" href="#步骤-3-执行导入">#</a> 步骤 3：执行导入</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/import-selective <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@export.zip&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=test&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;resource_keys=uuid-1,uuid-2&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;overwrite=false&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="迁移场景" tabindex="-1"><a class="header-anchor" href="#迁移场景">#</a> 迁移场景</h2><h3 id="场景-1-开发-→-测试-→-生产" tabindex="-1"><a class="header-anchor" href="#场景-1-开发-→-测试-→-生产">#</a> 场景 1：开发 → 测试 → 生产</h3><p>标准的 CI/CD 流程中，配置随代码一起推进：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">1. 开发环境配置</span>
<span class="line">   ↓ 验证通过后迁移</span>
<span class="line">2. 测试环境配置</span>
<span class="line">   ↓ 测试通过后迁移</span>
<span class="line">3. 生产环境配置</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>迁移步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 开发 → 测试</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/migrate <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;source_environment&quot;: &quot;dev&quot;,</span>
<span class="line">    &quot;source_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;target_environment&quot;: &quot;test&quot;,</span>
<span class="line">    &quot;target_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;overwrite&quot;: false</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 测试 → 生产</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/migrate <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;source_environment&quot;: &quot;test&quot;,</span>
<span class="line">    &quot;source_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;target_environment&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;target_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;overwrite&quot;: false</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景-2-主渠道-→-热修复渠道" tabindex="-1"><a class="header-anchor" href="#场景-2-主渠道-→-热修复渠道">#</a> 场景 2：主渠道 → 热修复渠道</h3><p>生产环境出现问题，需要创建热修复渠道：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">prod/main → prod/hotfix</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>步骤</strong>：</p><ol><li>创建 hotfix 渠道</li><li>从 main 渠道迁移配置</li><li>修改需要修复的配置</li><li>客户端切换到 hotfix 渠道</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 创建 hotfix 渠道</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/pipeline/create <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;environment_key&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;pipeline_key&quot;: &quot;hotfix&quot;,</span>
<span class="line">    &quot;pipeline_name&quot;: &quot;热修复渠道&quot;</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 迁移配置</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/migrate <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;source_environment&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;source_pipeline&quot;: &quot;main&quot;,</span>
<span class="line">    &quot;target_environment&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;target_pipeline&quot;: &quot;hotfix&quot;,</span>
<span class="line">    &quot;overwrite&quot;: true</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景-3-批量同步" tabindex="-1"><a class="header-anchor" href="#场景-3-批量同步">#</a> 场景 3：批量同步</h3><p>将配置同步到多个目标：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># sync.sh - 批量同步脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">SOURCE_ENV</span><span class="token operator">=</span><span class="token string">&quot;dev&quot;</span></span>
<span class="line"><span class="token assign-left variable">SOURCE_PIPELINE</span><span class="token operator">=</span><span class="token string">&quot;main&quot;</span></span>
<span class="line"><span class="token assign-left variable">TARGETS</span><span class="token operator">=</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token string">&quot;test:main&quot;</span></span>
<span class="line">  <span class="token string">&quot;staging:main&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">target</span> <span class="token keyword">in</span> <span class="token string">&quot;<span class="token variable">\${TARGETS<span class="token punctuation">[</span>@<span class="token punctuation">]</span>}</span>&quot;</span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">  <span class="token assign-left variable"><span class="token environment constant">IFS</span></span><span class="token operator">=</span><span class="token string">&#39;:&#39;</span> <span class="token builtin class-name">read</span> <span class="token parameter variable">-r</span> <span class="token function">env</span> pipeline <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$target</span>&quot;</span></span>
<span class="line">  </span>
<span class="line">  <span class="token builtin class-name">echo</span> <span class="token string">&quot;Migrating to <span class="token variable">$env</span>/<span class="token variable">$pipeline</span>...&quot;</span></span>
<span class="line">  </span>
<span class="line">  <span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/migrate <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token parameter variable">-d</span> <span class="token string">&quot;{</span>
<span class="line">      <span class="token entity" title="\\&quot;">\\&quot;</span>source_environment<span class="token entity" title="\\&quot;">\\&quot;</span>: <span class="token entity" title="\\&quot;">\\&quot;</span><span class="token variable">$SOURCE_ENV</span><span class="token entity" title="\\&quot;">\\&quot;</span>,</span>
<span class="line">      <span class="token entity" title="\\&quot;">\\&quot;</span>source_pipeline<span class="token entity" title="\\&quot;">\\&quot;</span>: <span class="token entity" title="\\&quot;">\\&quot;</span><span class="token variable">$SOURCE_PIPELINE</span><span class="token entity" title="\\&quot;">\\&quot;</span>,</span>
<span class="line">      <span class="token entity" title="\\&quot;">\\&quot;</span>target_environment<span class="token entity" title="\\&quot;">\\&quot;</span>: <span class="token entity" title="\\&quot;">\\&quot;</span><span class="token variable">$env</span><span class="token entity" title="\\&quot;">\\&quot;</span>,</span>
<span class="line">      <span class="token entity" title="\\&quot;">\\&quot;</span>target_pipeline<span class="token entity" title="\\&quot;">\\&quot;</span>: <span class="token entity" title="\\&quot;">\\&quot;</span><span class="token variable">$pipeline</span><span class="token entity" title="\\&quot;">\\&quot;</span>,</span>
<span class="line">      <span class="token entity" title="\\&quot;">\\&quot;</span>overwrite<span class="token entity" title="\\&quot;">\\&quot;</span>: false</span>
<span class="line">    }&quot;</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;Migration completed!&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="冲突处理" tabindex="-1"><a class="header-anchor" href="#冲突处理">#</a> 冲突处理</h2><h3 id="冲突类型" tabindex="-1"><a class="header-anchor" href="#冲突类型">#</a> 冲突类型</h3><table><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><code>new</code></td><td>目标不存在，将创建新配置</td></tr><tr><td><code>same</code></td><td>内容相同，无需处理</td></tr><tr><td><code>conflict</code></td><td>内容不同，需要决定处理方式</td></tr></tbody></table><h3 id="处理策略" tabindex="-1"><a class="header-anchor" href="#处理策略">#</a> 处理策略</h3><ol><li><strong>跳过（overwrite: false）</strong>：保留目标配置，跳过冲突</li><li><strong>覆盖（overwrite: true）</strong>：使用源配置覆盖目标</li></ol><h3 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践">#</a> 最佳实践</h3><div class="hint-container tip"><p class="hint-container-title">建议</p><p>生产环境迁移时，建议先预览，确认冲突情况后再决定处理方式。</p></div><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 先预览</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/import-preview <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@export.zip&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=prod&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 根据预览结果决定是否覆盖</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="迁移最佳实践" tabindex="-1"><a class="header-anchor" href="#迁移最佳实践">#</a> 迁移最佳实践</h2><h3 id="迁移前检查清单" tabindex="-1"><a class="header-anchor" href="#迁移前检查清单">#</a> 迁移前检查清单</h3><ul><li>[ ] 确认目标环境和渠道已创建</li><li>[ ] 确认目标环境是否有同名配置</li><li>[ ] 确认资源引用是否需要调整</li><li>[ ] 备份目标环境现有配置</li></ul><h3 id="迁移后验证" tabindex="-1"><a class="header-anchor" href="#迁移后验证">#</a> 迁移后验证</h3><ol><li><strong>配置完整性</strong>：检查所有配置是否正确迁移</li><li><strong>资源可用性</strong>：确认关联资源可访问</li><li><strong>功能测试</strong>：在目标环境进行功能验证</li><li><strong>回滚准备</strong>：保留迁移前的备份</li></ol><h3 id="审计日志" tabindex="-1"><a class="header-anchor" href="#审计日志">#</a> 审计日志</h3><p>建议记录迁移操作：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">日期: 2024-03-07 14:30</span>
<span class="line">操作: 配置迁移</span>
<span class="line">源: dev/main</span>
<span class="line">目标: test/main</span>
<span class="line">配置数: 15</span>
<span class="line">结果: 成功</span>
<span class="line">操作人: admin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h2><h3 id="q-迁移会影响源环境配置吗" tabindex="-1"><a class="header-anchor" href="#q-迁移会影响源环境配置吗">#</a> Q: 迁移会影响源环境配置吗？</h3><p>A: 不会。迁移是复制操作，源环境配置保持不变。</p><h3 id="q-可以跨环境类型迁移吗" tabindex="-1"><a class="header-anchor" href="#q-可以跨环境类型迁移吗">#</a> Q: 可以跨环境类型迁移吗？</h3><p>A: 可以。例如从 SQLite 实例迁移到 MySQL 实例，通过导出/导入方式。</p><h3 id="q-资源文件会一起迁移吗" tabindex="-1"><a class="header-anchor" href="#q-资源文件会一起迁移吗">#</a> Q: 资源文件会一起迁移吗？</h3><p>A: 是的。迁移配置时，关联的资源文件会一并迁移。</p><h3 id="q-迁移失败如何处理" tabindex="-1"><a class="header-anchor" href="#q-迁移失败如何处理">#</a> Q: 迁移失败如何处理？</h3><p>A: 迁移是原子操作，失败的配置不会影响已成功的配置。可以重新执行迁移。</p><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步">#</a> 下一步</h2><ul><li><a href="./export">导出配置</a> - 导出配置备份</li><li><a href="../integration/frontend">平台对接</a> - 集成到你的项目</li></ul>`,68)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};